VocabularyDeck withVocabularyMetadata(VocabularyDeck deck) => VocabularyDeck(
  id: deck.id,
  title: deck.title,
  subtitle: deck.subtitle,
  cover: deck.cover,
  note: deck.note,
  cards: List.unmodifiable([
    for (final card in deck.cards) attachMetadata(deck, card),
  ]),
);

VocabularyCard attachMetadata(VocabularyDeck deck, VocabularyCard card) {
  final origin =
      card.reviewIdentity ?? ReviewIdentity(deckId: deck.id, cardId: card.id);
  final metadata = vocabularyMetadata['${origin.deckId}.${origin.cardId}'];
  final words =
      vocabularyWords['${origin.deckId}.${origin.cardId}'] ?? card.words;
  final labels = {
    ...?metadata?.$2,
    ...card.labels,
    for (final word in words) ...word.labels,
  };
  return card.withMetadata(
    addedWeek: metadata?.$1,
    labels: labels.toList(growable: false),
    words: words,
  );
}
